const allItems = $input.all();
let jobs = [];
let posts = [];
for (const item of allItems) {
  const d = item.json.data;
  let jobArray = null;
  if (Array.isArray(d)) {
    jobArray = d;
  } else if (d && Array.isArray(d.jobs)) {
    jobArray = d.jobs;
  } else if (d && typeof d === 'object') {
    jobArray = Object.values(d);
  }
  if (jobArray) {
    jobs = jobArray.filter(function(j) { return j && (j.job_title || j.title); }).slice(0, 30).map(function(j) {
      return {
        type: 'job',
        title: j.job_title || j.title,
        company: j.employer_name || j.company,
        location: j.job_city ? (j.job_city + ', ' + j.job_country) : (j.job_country || j.location || ''),
        link: j.job_apply_link || j.link || j.url,
        description: (j.job_description || j.description || '').slice(0, 300)
      };
    });
  } else if (item.json.title) {
    posts.push({
      type: 'post',
      title: item.json.title,
      link: item.json.link,
      description: (item.json.contentSnippet || item.json.content || '').slice(0, 300)
    });
  }
}
posts = posts.slice(0, 10);
return [{ json: { items: jobs.concat(posts) } }];

