function getProfile() {
  try { return $('Interest Profile (edit me)').first().json; } catch (e) {}
  try { return $('Prepare Live Query').first().json; } catch (e) {}
  return {};
}
const profile = getProfile();
const kw = encodeURIComponent(profile.job_search_query || '');
const loc = encodeURIComponent(profile.job_location || '');
const linkedInUrl = 'https://www.linkedin.com/jobs/search/?keywords=' + kw + '&location=' + loc;

const output = $input.first().json;
let items = [];

if (Array.isArray(output.items)) {
  items = output.items.map(function(it) {
    return {
      type: it.type,
      title: it.title,
      company_or_source: it.company || 'LinkedIn',
      link: it.link,
      reason: 'Keyword match (AI ranking currently off)'
    };
  });
} else {
  let raw = '';
  if (typeof output.content === 'string') { raw = output.content; }
  else if (Array.isArray(output.content)) {
    const textBlock = output.content.find(function(c) { return c.type === 'text'; });
    raw = textBlock ? textBlock.text : '';
  } else if (output.text) { raw = output.text; }
  else if (output.response) { raw = output.response; }
  else if (output.output) { raw = output.output; }
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { items = JSON.parse(cleaned); } catch (e) { items = []; }
  if (!Array.isArray(items)) { items = []; }
}

const header = 'Your Daily Match Digest\n\n🔗 View live results on LinkedIn: ' + linkedInUrl + '\n\n';
if (!items.length) {
  return [{ json: { message: header + 'No strong matches today.' } }];
}

const MAX_LEN = 3800;
const chunks = [];
let current = header;
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const label = it.type === 'job' ? 'JOB' : 'POST';
  const entry = (i + 1) + '. [' + label + '] ' + it.title + '\n' + (it.company_or_source || '') + '\n' + it.reason + '\n' + it.link + '\n\n';
  if ((current + entry).length > MAX_LEN) {
    chunks.push(current);
    current = entry;
  } else {
    current += entry;
  }
}
if (current) chunks.push(current);

return chunks.map(function(c) { return { json: { message: c } }; });

const msg = $json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat ? msg.chat.id : null;

const countryMap = {
  'usa': 'us', 'united states': 'us', 'us': 'us', 'america': 'us',
  'france': 'fr', 'tunisia': 'tn', 'canada': 'ca', 'uk': 'gb', 'united kingdom': 'gb',
  'england': 'gb', 'germany': 'de', 'spain': 'es', 'italy': 'it', 'morocco': 'ma',
  'algeria': 'dz', 'egypt': 'eg', 'india': 'in', 'netherlands': 'nl', 'belgium': 'be',
  'switzerland': 'ch', 'uae': 'ae', 'dubai': 'ae', 'saudi arabia': 'sa', 'australia': 'au',
  'ireland': 'ie', 'portugal': 'pt', 'remote': 'us'
};

let query = text;
let location = 'Remote';
const match = text.match(/^(.*)\s+in\s+([A-Za-z\s]+)$/i);
if (match) {
  query = match[1].trim();
  location = match[2].trim();
}

const countryCode = countryMap[location.toLowerCase()] || 'us';

